def parse(row):
 text=row.get('text','').strip();lines=text.splitlines();last=lines[-1] if lines else ''
 # Only naturally finished responses count. A cut-off verdict is not evidence of completion.
 verdict=last[9:] if row['status']=='stop' and last in ['Verdict: PASS','Verdict: FLAG'] else 'missing'
 fields={}
 for key in ['Lines','Fault','Fails when','Input','Expected output','Actual output']:
  match=re.search(r'^'+re.escape(key)+r':\s*(.*?)(?=\n(?:Lines|Fault|Fails when|Input|Expected output|Actual output|Verdict):|\Z)',text,re.M|re.S)
  if match:fields[key]=match.group(1).strip()
 analysis=re.search(r'^Analysis:\s*(.*?)(?=\n(?:Lines|Verdict):|\Z)',text,re.M|re.S)
 for key in ['Input','Expected output','Actual output']:
  try:fields[key+'_parsed']=json.loads(fields[key]);assert isinstance(fields[key+'_parsed'],str)
  except (KeyError,ValueError,AssertionError):fields[key+'_parsed']=None
 return dict(verdict=verdict,status=row['status'],text=text,fields=fields,analysis_words=len(analysis.group(1).split()) if analysis else None,layout_complete=bool(analysis) and (verdict=='PASS' or verdict=='FLAG' and all(k in fields for k in ['Lines','Fault','Fails when','Input','Expected output','Actual output']) and all(fields[k+'_parsed'] is not None for k in ['Input','Expected output','Actual output'])))
